const darkButton=document.querySelector("#dark-button");const lightButton=document.querySelector("#light-button");darkButton?.addEventListener("click",()=>setTheme("dark"));lightButton?.addEventListener("click",()=>setTheme("light"));setTheme(localStorage.getItem("marketplace-theme")||"dark");function setTheme(theme){document.documentElement.dataset.theme=theme;localStorage.setItem("marketplace-theme",theme);darkButton?.classList.toggle("active",theme==="dark");lightButton?.classList.toggle("active",theme==="light")}